22	// ---- A small set of CSS named colors (used by the parser) -------------------
23	export const NAMED_COLORS: Record<string, string> = {
24	  black: "#000000", white: "#ffffff", red: "#ff0000", green: "#008000",
25	  blue: "#0000ff", yellow: "#ffff00", orange: "#ffa500", purple: "#800080",
26	  gray: "#808080", grey: "#808080", silver: "#c0c0c0", maroon: "#800000",
27	  olive: "#808000", lime: "#00ff00", aqua: "#00ffff", teal: "#008080",
28	  navy: "#000080", fuchsia: "#ff00ff", magenta: "#ff00ff", cyan: "#00ffff",
29	  pink: "#ffc0cb", brown: "#a52a2a", gold: "#ffd700", indigo: "#4b0082",
