39	// =============================================================================
40	// Hex <-> RGB
41	// =============================================================================
42	export function hexToRgb(hex: string): RGB | null {
43	  let h = hex.trim().replace(/^#/, "");
44	  if (h.length === 3 || h.length === 4) {
45	    h = h.split("").map((c) => c + c).join("");
46	  }
47	  if (h.length === 6 || h.length === 8) {
48	    const r = parseInt(h.slice(0, 2), 16);
49	    const g = parseInt(h.slice(2, 4), 16);
50	    const b = parseInt(h.slice(4, 6), 16);
51	    if ([r, g, b].some(Number.isNaN)) return null;
52	    return { r, g, b };
53	  }
54	  return null;
55	}
