146	// =============================================================================
147	// Contrast & readability (WCAG)
148	// =============================================================================
149	export function relativeLuminance({ r, g, b }: RGB): number {
150	  const ch = (c: number) => {
151	    const s = c / 255;
152	    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
153	  };
154	  return 0.2126 * ch(r) + 0.7152 * ch(g) + 0.0722 * ch(b);
155	}
156	
157	export function contrastRatio(a: RGB, b: RGB): number {
158	  const la = relativeLuminance(a);
159	  const lb = relativeLuminance(b);
160	  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
161	  return (hi + 0.05) / (lo + 0.05);
162	}
163	
164	/** Returns "#000000" or "#ffffff" — whichever is more readable on `bg`. */
165	export function readableText(bg: RGB): string {
166	  const white = { r: 255, g: 255, b: 255 };
167	  const black = { r: 0, g: 0, b: 0 };
168	  return contrastRatio(bg, white) >= contrastRatio(bg, black) ? "#ffffff" : "#000000";
169	}
170	
171	export function readableTextHex(hex: string): string {
172	  const rgb = hexToRgb(hex);
173	  return rgb ? readableText(rgb) : "#000000";
174	}
175	
176	export const wcagLabel = (ratio: number): string => {
177	  if (ratio >= 7) return "AAA";
178	  if (ratio >= 4.5) return "AA";
179	  if (ratio >= 3) return "AA Large";
180	  return "Fail";
181	};
182	
183	// =============================================================================
184	// Harmony schemes — from a base hex, return an array of hex colors.
185	// =============================================================================
186	export type Scheme =
187	  | "complementary"
188	  | "analogous"
189	  | "triadic"
190	  | "tetradic"
191	  | "split-complementary"
192	  | "monochromatic"
193	  | "shades";
194	
195	const rotate = (h: number, deg: number) => (((h + deg) % 360) + 360) % 360;
196	
197	export function generateScheme(baseHex: string, scheme: Scheme, count = 5): string[] {
198	  const base = hexToHsl(baseHex);
199	  if (!base) return [baseHex];
200	  const { h, s, l } = base;
201	
202	  const fromHues = (hues: number[]): string[] => {
203	    // Distribute `count` swatches across the anchor hues, varying lightness
204	    // gently so even a 5-swatch complementary scheme feels full.
205	    const out: string[] = [];
206	    const per = Math.max(1, Math.ceil(count / hues.length));
207	    for (const hue of hues) {
208	      for (let i = 0; i < per && out.length < count; i++) {
209	        const lift = per === 1 ? 0 : (i - (per - 1) / 2) * 14;
210	        out.push(hslToHex({ h: hue, s: clamp(s, 8, 100), l: clamp(l + lift, 8, 94) }));
211	      }
212	    }
213	    return out.slice(0, count);
214	  };
215	
216	  switch (scheme) {
217	    case "complementary":
218	      return fromHues([h, rotate(h, 180)]);
219	    case "analogous":
220	      return fromHues([rotate(h, -60), rotate(h, -30), h, rotate(h, 30), rotate(h, 60)]);
221	    case "triadic":
222	      return fromHues([h, rotate(h, 120), rotate(h, 240)]);
223	    case "tetradic":
224	      return fromHues([h, rotate(h, 90), rotate(h, 180), rotate(h, 270)]);
225	    case "split-complementary":
226	      return fromHues([h, rotate(h, 150), rotate(h, 210)]);
227	    case "monochromatic": {
228	      const out: string[] = [];
229	      for (let i = 0; i < count; i++) {
230	        const t = count === 1 ? 0.5 : i / (count - 1);
231	        out.push(hslToHex({ h, s: clamp(s, 6, 100), l: clamp(18 + t * 70, 6, 96) }));
232	      }
233	      return out;
234	    }
235	    case "shades": {
236	      const out: string[] = [];
237	      for (let i = 0; i < count; i++) {
238	        const t = count === 1 ? 0.5 : i / (count - 1);
239	        out.push(hslToHex({ h, s, l: clamp(90 - t * 78, 6, 94) }));
240	      }
241	      return out;
242	    }
243	  }
244	}
245	
246	// =============================================================================
247	// Tonal ramps in the shape semantica's tokens.css expects.
248	// =============================================================================
249	
250	// Lightness/saturation targets per stop. Tuned to feel like Tailwind's slate
251	// (neutral) and blue (accent) ramps so generated themes look professional.
252	const NEUTRAL_STOPS: Array<[string, number, number]> = [
253	  // [stop, lightness, saturationScale(0..1 of base sat, floored)]
254	  ["50", 98, 0.6], ["100", 96, 0.7], ["200", 91, 0.8], ["300", 84, 0.9],
255	  ["400", 67, 1], ["500", 49, 1], ["600", 39, 1], ["700", 29, 1],
256	  ["800", 18, 1], ["900", 11, 1], ["950", 4, 1],
257	];
258	
259	const ACCENT_STOPS: Array<[string, number]> = [
260	  ["300", 76], ["400", 67], ["500", 59], ["600", 51], ["700", 43],
261	];
262	
263	export interface SemanticaTokens {
264	  gray: Record<string, string>;
265	  accent: Record<string, string>;
266	  success: string;
267	  warning: string;
268	  danger: string;
269	}
270	
271	/**
272	 * Build a full semantica primitive palette from an accent color and an
273	 * optional neutral seed. The neutral ramp is subtly tinted toward the chosen
274	 * hue (or the accent hue) so the theme feels cohesive rather than dead-gray.
275	 */
276	export function buildSemanticaTokens(
277	  accentHex: string,
278	  neutralHex?: string,
279	): SemanticaTokens {
280	  const accent = hexToHsl(accentHex) ?? { h: 217, s: 91, l: 60 };
281	  const neutralSeed = neutralHex ? hexToHsl(neutralHex) : null;
282	  const neutralHue = neutralSeed ? neutralSeed.h : accent.h;
283	  // Keep neutrals neutral: a low, fixed-ish chroma tinted toward the hue.
284	  const neutralSat = neutralSeed ? clamp(neutralSeed.s, 4, 22) : 14;
285	
286	  const gray: Record<string, string> = {};
287	  for (const [stop, l, satScale] of NEUTRAL_STOPS) {
288	    gray[stop] = hslToHex({ h: neutralHue, s: clamp(neutralSat * satScale, 3, 24), l });
289	  }
290	
291	  const accentSat = clamp(accent.s, 45, 100);
292	  const accents: Record<string, string> = {};
293	  for (const [stop, l] of ACCENT_STOPS) {
294	    accents[stop] = hslToHex({ h: accent.h, s: accentSat, l });
295	  }
296	
297	  // Status colors: anchor hues, lightness/saturation matched to the accent's
298	  // vibrancy so they sit together. Hues are fixed (green/amber/red) on purpose.
299	  const status = (hue: number) =>
300	    hslToHex({ h: hue, s: clamp(accentSat, 55, 85), l: 50 });
301	
302	  return {
303	    gray,
304	    accent: accents,
305	    success: status(142),
306	    warning: hslToHex({ h: 38, s: 92, l: 50 }),
307	    danger: hslToHex({ h: 0, s: 75, l: 51 }),
308	  };
309	}
310	
311	// =============================================================================
312	// Misc helpers
313	// =============================================================================
314	
315	/** Distance in RGB space — cheap near-duplicate test for de-duping palettes. */
316	export function rgbDistance(a: RGB, b: RGB): number {
317	  return Math.sqrt((a.r - b.r) ** 2 + (a.g - b.g) ** 2 + (a.b - b.b) ** 2);
318	}
319	
320	export function normalizeHex(input: string): string | null {
321	  const rgb = parseColor(input);
322	  return rgb ? rgbToHex(rgb) : null;
323	}
324	
325	/** Random pleasant hex (good saturation/lightness range). */
326	export function randomHex(seed: number): string {
327	  // Deterministic-ish given a seed so callers control variation (no Math.random
328	  // needed). Golden-ratio hue stepping keeps successive hues well spread.
329	  const h = (seed * 137.508) % 360;
330	  const s = 55 + ((seed * 53) % 35);
331	  const l = 45 + ((seed * 29) % 20);
332	  return hslToHex({ h, s, l });
333	}
