326	            <div className="ramp">
327	              {grayStops.map(([k, v]) => (
328	                <div key={k} style={{ background: v, color: readableTextHex(v) }} title={`gray-${k}: ${v}`}>{k}</div>
329	              ))}
330	            </div>
331	            <div className="ramp-label">Accent ramp — <code>--sui-accent-*</code></div>
332	            <div className="ramp">
333	              {accentStops.map(([k, v]) => (
334	                <div key={k} style={{ background: v, color: readableTextHex(v) }} title={`accent-${k}: ${v}`}>{k}</div>
335	              ))}
336	            </div>
