"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  buildSemanticaTokens,
  generateScheme,
  normalizeHex,
  randomHex,
  readableTextHex,
  Scheme,
  SemanticaTokens,
} from "@/lib/color";
import {
  Swatch,
  toCssVars,
  toJson,
  toScss,
  toSemanticaOverride,
  toSvg,
  toTailwind,
} from "@/lib/export";
import { buildBookmarklet, buildSnippet } from "@/lib/bookmarklet";

interface Sw { hex: string; locked: boolean; }

const SCHEMES: { id: Scheme; label: string }[] = [
  { id: "analogous", label: "Analogous" },
  { id: "complementary", label: "Complementary" },
  { id: "triadic", label: "Triadic" },
  { id: "tetradic", label: "Tetradic" },
  { id: "split-complementary", label: "Split" },
  { id: "monochromatic", label: "Mono" },
  { id: "shades", label: "Shades" },
];

const EXPORTS = [
  { id: "semantica", label: "semantica", file: "theme.css" },
  { id: "css", label: "CSS vars", file: "palette.css" },
  { id: "tailwind", label: "Tailwind", file: "tailwind.config.js" },
  { id: "scss", label: "SCSS", file: "_palette.scss" },
  { id: "json", label: "JSON", file: "palette.json" },
  { id: "svg", label: "SVG", file: "palette.svg" },
] as const;
type ExportId = (typeof EXPORTS)[number]["id"];

function previewVars(t: SemanticaTokens, dark: boolean) {
  const v = dark
    ? {
        "--p-bg": t.gray["950"], "--p-surface": t.gray["900"], "--p-surface-alt": t.gray["800"],
        "--p-border": t.gray["800"], "--p-text": t.gray["100"], "--p-muted": t.gray["400"],
        "--p-accent": t.accent["500"], "--p-accent-hover": t.accent["400"],
        "--p-on-accent": readableTextHex(t.accent["500"]),
      }
    : {
        "--p-bg": t.gray["50"], "--p-surface": "#ffffff", "--p-surface-alt": t.gray["100"],
        "--p-border": t.gray["200"], "--p-text": t.gray["900"], "--p-muted": t.gray["500"],
        "--p-accent": t.accent["600"], "--p-accent-hover": t.accent["700"],
        "--p-on-accent": readableTextHex(t.accent["600"]),
      };
  return { ...v, "--p-success": t.success, "--p-warning": t.warning, "--p-danger": t.danger } as React.CSSProperties;
}

export default function Page() {
  const [accent, setAccent] = useState("#3b82f6");
  const [scheme, setScheme] = useState<Scheme>("analogous");
  const [count, setCount] = useState(6);
  const [tintNeutral, setTintNeutral] = useState(true);
  const [palette, setPalette] = useState<Sw[]>(() =>
    generateScheme("#3b82f6", "analogous", 6).map((hex) => ({ hex, locked: false })),
  );
  const [tick, setTick] = useState(1);
  const [tab, setTab] = useState<ExportId>("css");
  const [dark, setDark] = useState(false);
  const [neutralsToo, setNeutralsToo] = useState(false);
  const [copied, setCopied] = useState<string | null>(null);

  const bmRef = useRef<HTMLAnchorElement>(null);

  const tokens = useMemo(
    () => buildSemanticaTokens(accent, tintNeutral ? undefined : "#71717a"),
    [accent, tintNeutral],
  );

  const flash = useCallback((k: string) => {
    setCopied(k);
    window.setTimeout(() => setCopied((c) => (c === k ? null : c)), 1300);
  }, []);
  const copy = useCallback(async (text: string, k: string) => {
    try { await navigator.clipboard.writeText(text); flash(k); } catch { /* blocked */ }
  }, [flash]);

  const regenerate = useCallback((base: string, sc: Scheme, n: number) => {
    const gen = generateScheme(base, sc, n);
    setPalette((prev) => {
      const out: Sw[] = [];
      for (let i = 0; i < n; i++) out.push(prev[i]?.locked ? prev[i] : { hex: gen[i] ?? base, locked: false });
      return out;
    });
  }, []);
  const applyAccent = useCallback((hex: string) => {
    const norm = normalizeHex(hex);
    if (!norm) return;
    setAccent(norm);
    regenerate(norm, scheme, count);
  }, [scheme, count, regenerate]);
  const shuffle = useCallback(() => {
    const next = tick + 1; setTick(next); applyAccent(randomHex(next * 7));
  }, [tick, applyAccent]);
  function toggleLock(i: number) {
    setPalette((p) => p.map((s, idx) => (idx === i ? { ...s, locked: !s.locked } : s)));
  }

  // Spacebar shuffles (unless typing).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement;
      if (e.code === "Space" && !["INPUT", "TEXTAREA", "SELECT"].includes(el?.tagName)) {
        e.preventDefault(); shuffle();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [shuffle]);

  const paletteHexes = palette.map((p) => p.hex);
  const bookmarklet = useMemo(
    () => buildBookmarklet(paletteHexes, { neutralsToo }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [paletteHexes.join(","), neutralsToo],
  );
  // React strips javascript: hrefs, so set it on the DOM node directly.
  useEffect(() => { bmRef.current?.setAttribute("href", bookmarklet); }, [bookmarklet]);

  const swatches: Swatch[] = palette.map((p) => ({ hex: p.hex }));
  const exportText = useMemo(() => {
    switch (tab) {
      case "semantica": return toSemanticaOverride(tokens);
      case "css": return toCssVars(swatches);
      case "tailwind": return toTailwind(swatches);
      case "scss": return toScss(swatches);
      case "json": return toJson(swatches);
      case "svg": return toSvg(swatches);
      default: return "";
    }
  }, [tab, tokens, swatches]);
  const currentExport = EXPORTS.find((e) => e.id === tab)!;
  function download() {
    const blob = new Blob([exportText], { type: tab === "svg" ? "image/svg+xml" : "text/plain" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob); a.download = currentExport.file; a.click();
    URL.revokeObjectURL(a.href);
  }

  const grayStops = Object.entries(tokens.gray);
  const accentStops = Object.entries(tokens.accent);

  return (
    <div className="wrap">
      <header className="masthead">
        <div className="brand">
          <span className="logo" aria-hidden />
          <div>
            <h1>Palette Studio</h1>
            <p>generate a palette, preview it, &amp; apply it to any live website</p>
          </div>
        </div>
        <div className="ghost">press <kbd>Space</kbd> to shuffle</div>
      </header>

      <div className="grid">
        {/* ---------------- LEFT ---------------- */}
        <div className="col">
          <section className="panel">
            <div className="section-title"><span className="num">1</span> Generate a palette</div>
            <label className="field">Seed / accent color</label>
            <div className="row">
              <input type="color" value={accent} onChange={(e) => applyAccent(e.target.value)} aria-label="Seed color" />
              <input type="text" className="mono" value={accent}
                onChange={(e) => setAccent(e.target.value)} onBlur={(e) => applyAccent(e.target.value)} />
              <button className="btn" onClick={shuffle}>Shuffle</button>
            </div>

            <label className="field" style={{ marginTop: 12 }}>Harmony</label>
            <div className="pills">
              {SCHEMES.map((s) => (
                <button key={s.id} className="pill" aria-pressed={scheme === s.id}
                  onClick={() => { setScheme(s.id); regenerate(accent, s.id, count); }}>{s.label}</button>
              ))}
            </div>

            <div className="row" style={{ marginTop: 12 }}>
              <span className="field" style={{ margin: 0, minWidth: 86 }}>Swatches: {count}</span>
              <input type="range" min={3} max={10} value={count} style={{ flex: 1 }}
                onChange={(e) => { const n = Number(e.target.value); setCount(n); regenerate(accent, scheme, n); }} />
            </div>

            <div className="palette">
              {palette.map((s, i) => (
                <div className="swatch" key={`${s.hex}-${i}`}>
                  <div className="chip" style={{ background: s.hex }} onClick={() => copy(s.hex, `sw-${i}`)} title="Copy">
                    <button className="lock" onClick={(e) => { e.stopPropagation(); toggleLock(i); }}
                      title={s.locked ? "Unlock" : "Lock"}>{s.locked ? "🔒" : "🔓"}</button>
                  </div>
                  <div className="meta">
                    <span className="hex">{s.hex}</span>
                    {copied === `sw-${i}`
                      ? <span className="flash">copied!</span>
                      : <button className="link" onClick={() => applyAccent(s.hex)}>set as accent</button>}
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section className="panel">
            <div className="section-title"><span className="num">2</span> Apply to any website</div>
            <p className="help">
              Drag the button below to your bookmarks bar, then click it on <strong>any</strong> site —
              it recolors the real, live page in your palette (and keeps recoloring as the page changes).
              No proxy, works everywhere, even YouTube.
            </p>

            <div className="bm-row">
              {/* href is set via ref because React strips javascript: URLs */}
              <a ref={bmRef} className="bookmarklet" draggable
                onClick={(e) => e.preventDefault()} title="Drag me to your bookmarks bar">
                🎨 Apply Palette
              </a>
              <span className="bm-hint">← drag to bookmarks bar</span>
            </div>

            <label className="check">
              <input type="checkbox" checked={neutralsToo} onChange={(e) => setNeutralsToo(e.target.checked)} />
              Recolor neutrals too (greys / backgrounds)
            </label>

            <div className="row wrap" style={{ marginTop: 10 }}>
              <button className="btn sm" onClick={() => copy(bookmarklet, "bm")}>
                {copied === "bm" ? "Copied!" : "Copy bookmarklet URL"}
              </button>
              <button className="btn sm" onClick={() => copy(buildSnippet(paletteHexes, { neutralsToo }), "snip")}>
                {copied === "snip" ? "Copied!" : "Copy console snippet"}
              </button>
            </div>
            <p className="help" style={{ marginTop: 8 }}>
              No bookmarks bar? Open the site, press F12 → Console, paste the snippet, Enter.
              Undo by reloading the page (or run <code>__rcStop()</code> then reload).
            </p>
          </section>

          <section className="panel">
            <div className="section-title"><span className="num">3</span> Export</div>
            <div className="tabs">
              {EXPORTS.map((e) => (
                <button key={e.id} className="tab" aria-selected={tab === e.id} onClick={() => setTab(e.id)}>{e.label}</button>
              ))}
            </div>
            {tab === "semantica" && (
              <label className="check" style={{ marginBottom: 8 }}>
                <input type="checkbox" checked={tintNeutral} onChange={(e) => setTintNeutral(e.target.checked)} />
                Tint neutral greys with the accent hue
              </label>
            )}
            <div className="row" style={{ marginBottom: 8 }}>
              <button className="btn sm primary" onClick={() => copy(exportText, "exp")}>{copied === "exp" ? "Copied!" : "Copy"}</button>
              <button className="btn sm" onClick={download}>Download {currentExport.file}</button>
            </div>
            <pre className="code">{exportText}</pre>
          </section>
        </div>

        {/* ---------------- RIGHT: live mockup preview ---------------- */}
        <div className="col">
          <section className="panel">
            <div className="spread" style={{ marginBottom: 14 }}>
              <div className="section-title" style={{ margin: 0 }}>Live preview</div>
              <div className="toolbar">
                <button className="pill" aria-pressed={!dark} onClick={() => setDark(false)}>Light</button>
                <button className="pill" aria-pressed={dark} onClick={() => setDark(true)}>Dark</button>
              </div>
            </div>

            <div className={`preview ${dark ? "dark" : ""}`} style={previewVars(tokens, dark)}>
              <div className="pv-nav">
                <div className="pv-brand"><span className="blob" /> Acme</div>
                <div className="pv-links">
                  <span>Product</span><span>Pricing</span><span>Docs</span>
                  <span style={{ color: "var(--p-accent)", fontWeight: 600 }}>Sign in</span>
                </div>
              </div>
              <div className="pv-hero">
                <h2>Your palette, <span className="grad">in context.</span></h2>
                <p>This whole mockup recolors from the palette on the left. Use the bookmarklet to
                  apply the same palette to any real website.</p>
                <div className="pv-actions">
                  <span className="pv-btn solid">Get started</span>
                  <span className="pv-btn ghost">Learn more</span>
                </div>
              </div>
              <div className="pv-cards">
                <div className="pv-card">
                  <span className="tag" style={{ background: "var(--p-accent)", color: "var(--p-on-accent)" }}>New</span>
                  <h3>Accent</h3><p>Buttons &amp; links use the accent ramp.</p>
                </div>
                <div className="pv-card">
                  <span className="tag" style={{ background: "var(--p-success)", color: "#fff" }}>Stable</span>
                  <h3>Surfaces</h3><p>Cards sit on tinted neutral greys.</p>
                </div>
                <div className="pv-card">
                  <span className="tag" style={{ background: "var(--p-warning)", color: "#1a1205" }}>Beta</span>
                  <h3>Status</h3><p>Success, warning &amp; danger stay legible.</p>
                </div>
              </div>
              <div className="pv-badges">
                <span className="pv-badge" style={{ background: "var(--p-success)" }}>Success</span>
                <span className="pv-badge" style={{ background: "var(--p-warning)", color: "#1a1205" }}>Warning</span>
                <span className="pv-badge" style={{ background: "var(--p-danger)" }}>Danger</span>
              </div>
              <div className="pv-input">
                <input placeholder="you@company.com" />
                <span className="pv-btn solid">Subscribe</span>
              </div>
            </div>

            <div className="ramp-label">Neutral ramp — <code>--sui-gray-*</code></div>
            <div className="ramp">
              {grayStops.map(([k, v]) => (
                <div key={k} style={{ background: v, color: readableTextHex(v) }} title={`gray-${k}: ${v}`}>{k}</div>
              ))}
            </div>
            <div className="ramp-label">Accent ramp — <code>--sui-accent-*</code></div>
            <div className="ramp">
              {accentStops.map(([k, v]) => (
                <div key={k} style={{ background: v, color: readableTextHex(v) }} title={`accent-${k}: ${v}`}>{k}</div>
              ))}
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

