:root {
  --bg: #0b0e14;
  --bg-grad: radial-gradient(1200px 600px at 85% -10%, #1a2130 0%, #0b0e14 55%);
  --panel: #121826;
  --panel-2: #0d1220;
  --border: #232a3b;
  --border-soft: #1a2030;
  --text: #e7ecf5;
  --muted: #9aa6bd;
  --subtle: #69748c;
  --accent: #7c9cff;
  --ok: #3ddc97;
  --bad: #ff8a8a;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 10px 30px -14px rgba(0,0,0,0.6);
  --mono: ui-monospace, "SF Mono", "Cascadia Code", "JetBrains Mono", Consolas, monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
* { box-sizing: border-box; margin: 0; }
html, body { height: 100%; }
body {
  background: var(--bg-grad), var(--bg); background-attachment: fixed;
  color: var(--text); font-family: var(--sans); line-height: 1.55; -webkit-font-smoothing: antialiased;
}
.mono { font-family: var(--mono); }
code { font-family: var(--mono); font-size: 0.9em; }
kbd { font-family: var(--mono); font-size: 0.78em; background: var(--panel-2); border: 1px solid var(--border);
  border-radius: 5px; padding: 1px 6px; }

.wrap { max-width: 1320px; margin: 0 auto; padding: 22px 18px 64px; }

.masthead { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 18px; flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 11px; }
.brand .logo { width: 38px; height: 38px; border-radius: 10px;
  background: conic-gradient(from 200deg, #ff6b6b, #ffd93d, #6bcb77, #4d96ff, #b78bff, #ff6b6b); box-shadow: var(--shadow); }
.brand h1 { font-size: 1.2rem; letter-spacing: -0.02em; }
.brand p { color: var(--muted); font-size: 0.8rem; }
.ghost { color: var(--muted); font-size: 0.8rem; }

.grid { display: grid; grid-template-columns: minmax(0, 440px) minmax(0, 1fr); gap: 18px; align-items: start; }
@media (max-width: 940px) { .grid { grid-template-columns: 1fr; } }
.col { min-width: 0; }
.col:last-child { position: sticky; top: 16px; }
@media (max-width: 940px) { .col:last-child { position: static; } }

.panel { background: linear-gradient(180deg, var(--panel), var(--panel-2)); border: 1px solid var(--border);
  border-radius: var(--radius); box-shadow: var(--shadow); padding: 16px; }
.panel + .panel { margin-top: 16px; }

.section-title { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.11em; color: var(--muted);
  margin-bottom: 12px; display: flex; align-items: center; gap: 8px; }
.section-title .num { display: inline-grid; place-items: center; width: 18px; height: 18px; border-radius: 5px;
  background: var(--accent); color: #0b0e14; font-size: 0.7rem; font-weight: 700; }
.spread { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.toolbar { display: flex; gap: 6px; }

.field { display: block; font-size: 0.76rem; color: var(--muted); margin-bottom: 6px; }
.help { color: var(--muted); font-size: 0.78rem; line-height: 1.5; }
.row { display: flex; gap: 8px; align-items: center; }
.row.wrap { flex-wrap: wrap; }

input[type="text"] { width: 100%; background: var(--panel-2); border: 1px solid var(--border); color: var(--text);
  border-radius: var(--radius-sm); padding: 9px 11px; font-size: 0.88rem; outline: none; }
input[type="text"]:focus { border-color: var(--accent); }
input[type="color"] { width: 46px; height: 38px; padding: 0; border: 1px solid var(--border);
  border-radius: var(--radius-sm); background: var(--panel-2); cursor: pointer; }
input[type="range"] { accent-color: var(--accent); }

.btn { appearance: none; border: 1px solid var(--border); background: var(--panel-2); color: var(--text);
  border-radius: var(--radius-sm); padding: 9px 13px; font-size: 0.85rem; font-weight: 600; cursor: pointer;
  white-space: nowrap; transition: border-color 0.14s, background 0.14s, transform 0.07s; display: inline-flex;
  align-items: center; justify-content: center; gap: 6px; }
.btn:hover { border-color: var(--accent); }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn.primary { background: linear-gradient(180deg, var(--accent), #5f7ff0); border-color: transparent; color: #08101f; }
.btn.primary:hover { filter: brightness(1.06); }
.btn.sm { padding: 6px 10px; font-size: 0.79rem; }

.pills { display: flex; flex-wrap: wrap; gap: 6px; }
.pill { border: 1px solid var(--border); background: var(--panel-2); color: var(--muted); border-radius: 999px;
  padding: 5px 11px; font-size: 0.77rem; cursor: pointer; transition: all 0.12s; }
.pill:hover { border-color: var(--accent); color: var(--text); }
.pill[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: #08101f; font-weight: 600; }
.check { display: flex; gap: 8px; align-items: center; font-size: 0.78rem; color: var(--muted); margin-top: 10px; }
.check input { width: auto; }

/* working palette */
.palette { display: grid; grid-template-columns: repeat(auto-fill, minmax(88px, 1fr)); gap: 9px; margin-top: 14px; }
.swatch { border-radius: var(--radius-sm); border: 1px solid var(--border); overflow: hidden; background: var(--panel-2); }
.swatch .chip { height: 74px; cursor: pointer; display: flex; align-items: flex-start; justify-content: flex-end; padding: 6px; }
.swatch .lock { background: rgba(0,0,0,0.28); color: #fff; border: none; border-radius: 6px; width: 24px; height: 24px;
  cursor: pointer; font-size: 0.74rem; display: grid; place-items: center; }
.swatch .meta { padding: 7px 8px; display: flex; flex-direction: column; gap: 1px; }
.swatch .hex { font-family: var(--mono); font-size: 0.74rem; }
.swatch .link { background: none; border: none; padding: 0; color: var(--subtle); font-size: 0.66rem; cursor: pointer; text-align: left; }
.swatch .link:hover { color: var(--accent); }
.swatch .flash { color: var(--ok); font-size: 0.66rem; }

/* bookmarklet */
.bm-row { display: flex; align-items: center; gap: 12px; margin: 12px 0 4px; flex-wrap: wrap; }
.bookmarklet { display: inline-flex; align-items: center; gap: 8px; cursor: grab; user-select: none;
  background: linear-gradient(180deg, var(--accent), #5f7ff0); color: #08101f; font-weight: 700; font-size: 0.92rem;
  padding: 11px 18px; border-radius: 10px; text-decoration: none; box-shadow: var(--shadow); border: 1px solid transparent; }
.bookmarklet:active { cursor: grabbing; }
.bm-hint { color: var(--subtle); font-size: 0.74rem; }

/* export */
.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--border); margin-bottom: 12px; flex-wrap: wrap; }
.tab { background: none; border: none; color: var(--muted); padding: 7px 11px; cursor: pointer; font-size: 0.8rem;
  font-weight: 600; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.tab:hover { color: var(--text); }
.tab[aria-selected="true"] { color: var(--text); border-bottom-color: var(--accent); }
pre.code { background: #080b12; border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 13px;
  overflow: auto; max-height: 280px; font-family: var(--mono); font-size: 0.76rem; line-height: 1.5; color: #cfe0ff; }

/* ramps */
.ramp-label { font-size: 0.72rem; color: var(--muted); margin: 14px 0 5px; }
.ramp { display: flex; border-radius: var(--radius-sm); overflow: hidden; border: 1px solid var(--border); }
.ramp > div { flex: 1; height: 34px; display: grid; place-items: center; font-size: 0.6rem; font-family: var(--mono); }

/* ===== live mockup preview (recolors from --p-* vars) ===== */
.preview {
  --p-bg: #f8fafc; --p-surface: #fff; --p-surface-alt: #f1f5f9; --p-border: #e2e8f0;
  --p-text: #0f172a; --p-muted: #64748b; --p-accent: #2563eb; --p-accent-hover: #1d4ed8;
  --p-on-accent: #fff; --p-success: #22c55e; --p-warning: #f59e0b; --p-danger: #dc2626;
  background: var(--p-bg); color: var(--p-text); border-radius: var(--radius-sm);
  border: 1px solid var(--border); padding: 22px; overflow: hidden;
}
.preview * { transition: background 0.25s, color 0.25s, border-color 0.25s; }
.pv-nav { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }
.pv-brand { display: flex; align-items: center; gap: 9px; font-weight: 700; }
.pv-brand .blob { width: 24px; height: 24px; border-radius: 7px; background: var(--p-accent); }
.pv-links { display: flex; gap: 16px; color: var(--p-muted); font-size: 0.84rem; }
.pv-hero { padding: 8px 0 18px; }
.pv-hero h2 { font-size: 1.85rem; letter-spacing: -0.02em; line-height: 1.1; margin-bottom: 8px; }
.pv-hero h2 .grad { background: linear-gradient(90deg, var(--p-accent), var(--p-accent-hover));
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.pv-hero p { color: var(--p-muted); max-width: 46ch; margin-bottom: 16px; }
.pv-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.pv-btn { border-radius: 8px; padding: 10px 16px; font-weight: 600; font-size: 0.86rem; border: 1px solid transparent; }
.pv-btn.solid { background: var(--p-accent); color: var(--p-on-accent); }
.pv-btn.ghost { background: transparent; color: var(--p-text); border-color: var(--p-border); }
.pv-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 18px; }
@media (max-width: 560px) { .pv-cards { grid-template-columns: 1fr; } }
.pv-card { background: var(--p-surface); border: 1px solid var(--p-border); border-radius: 10px; padding: 14px; }
.pv-card .tag { display: inline-block; font-size: 0.66rem; font-weight: 700; padding: 2px 8px; border-radius: 999px; margin-bottom: 8px; }
.pv-card h3 { font-size: 0.96rem; margin-bottom: 4px; }
.pv-card p { font-size: 0.8rem; color: var(--p-muted); }
.pv-badges { display: flex; gap: 8px; margin-top: 16px; flex-wrap: wrap; }
.pv-badge { font-size: 0.72rem; font-weight: 700; padding: 4px 10px; border-radius: 999px; color: #fff; }
.pv-input { margin-top: 16px; display: flex; gap: 8px; max-width: 420px; }
.pv-input input { flex: 1; background: var(--p-surface); border: 1px solid var(--p-border); color: var(--p-text);
  border-radius: 8px; padding: 9px 12px; font-size: 0.84rem; }
.preview.dark { --p-bg: #020617; --p-surface: #0f172a; --p-surface-alt: #1e293b; --p-border: #1e293b;
  --p-text: #f1f5f9; --p-muted: #94a3b8; }

