.swatch .chip { height: 74px; cursor: pointer; display: flex; align-items: flex-start; justify-content: flex-end; padding: 6px; }
.swatch .chip:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.swatch .lock { background: rgba(0,0,0,0.28); color: #fff; border: none; border-radius: 6px; width: 24px; height: 24px;
  cursor: pointer; font-size: 0.74rem; display: grid; place-items: center; }
.swatch .meta { padding: 7px 8px; display: flex; flex-direction: column; gap: 1px; }
.swatch .hex { font-family: var(--mono); font-size: 0.74rem; }
.swatch .contrast { display: flex; gap: 4px; margin: 3px 0 1px; flex-wrap: wrap; }
.swatch .cbadge { font-size: 0.6rem; font-weight: 700; padding: 1px 5px; border-radius: 999px; color: #08101f; background: var(--ok); }
.swatch .cbadge.fail { background: var(--bad); color: #2b0b0b; }
.swatch .link { background: none; border: none; padding: 0; color: var(--subtle); font-size: 0.66rem; cursor: pointer; text-align: left; }
.swatch .link:hover { color: var(--accent); }
.swatch .flash { color: var(--ok); font-size: 0.66rem; }
